package org.example;

import org.example.models.ViewModel;

import javafx.geometry.Point2D;
import com.sun.prism.paint.Paint;

import org.example.entities.Player;
import org.example.enums.Direction;

import java.util.Arrays;

import org.example.controllers.ViewController;

import javafx.animation.AnimationTimer;
import javafx.application.Application;
import javafx.scene.Scene;
import javafx.scene.canvas.Canvas;
import javafx.scene.canvas.GraphicsContext;
import javafx.scene.input.KeyCode;
import javafx.scene.layout.StackPane;
import javafx.scene.paint.Color;
import javafx.scene.robot.Robot;
import javafx.stage.Screen;
import javafx.stage.Stage;

public class App extends Application{

  static final int WIDTH = 640;
  static final int HEIGHT = 480;
  private boolean isProgramaticMouseMovement = false;
  private boolean mouseCaptured = false;
  @Override
  public void start(Stage stage){
    ViewModel vModel = new ViewModel(new Player(3,6));
    
    ViewController vController = new ViewController(vModel);
  
    Canvas canvas = new Canvas(WIDTH, HEIGHT);
    GraphicsContext gc = canvas.getGraphicsContext2D();

    StackPane root = new StackPane(canvas);
    Scene scene = new Scene(root, WIDTH, HEIGHT);

    scene.setOnMouseClicked(event -> {
      if (!mouseCaptured){
        isProgramaticMouseMovement = true;
        Point2D screenCenter = scene.getRoot().localToScreen(scene.getWidth()/2,scene.getHeight()/2);
        double sceneX = scene.getWindow().getX();
        double sceneY = scene.getWindow().getY();
        System.out.println("X: " + (sceneX + screenCenter.getX()) + " Y: " + (sceneY + screenCenter.getY()));
        try{
          new Robot().mouseMove((int)Math.round(screenCenter.getX()), (int)Math.round(screenCenter.getY()));
          isProgramaticMouseMovement = true;
          mouseCaptured = true;

        } catch (Exception e){
          e.printStackTrace();
        }
        System.out.println("Mouse: Captured");

      }
    });
    //TODO: Stop creating new robot each frame, instantiate a robot as a instance variable and reuse. 
    scene.setOnMouseMoved(event -> {
      if (isProgramaticMouseMovement){
        isProgramaticMouseMovement = false;
        return;
      }
      if (mouseCaptured){
        //Grabbing the current monitors output scale 
        Screen screen = Screen.getScreensForRectangle(stage.getX(), stage.getY(), 1, 1).get(0);
        double mouseX = event.getScreenX();
        Point2D sceneCenter = canvas.localToScreen(canvas.getWidth()/2, canvas.getHeight()/2);
        double mouseDeltaX = (mouseX - sceneCenter.getX());

        //Ignoring any deltas that are less than the output scale, this prevents the gittery rotations.
        if (Math.abs(mouseDeltaX) <= screen.getOutputScaleX()){
          return;
        }
        //Rounding the delta value, this gives consistent delta values across different monitors.
        vController.rotate(Math.round(mouseDeltaX));
        
        
        //Moving the cursor back to the center of the game window. 
        try{
          new Robot().mouseMove((int)Math.round(sceneCenter.getX()), (int)Math.round(sceneCenter.getY()));
          isProgramaticMouseMovement = true;

        } catch (Exception e){
          e.printStackTrace();
        }
      }
    });


    scene.setOnKeyPressed(event -> {
      KeyCode code = event.getCode();
      switch(code){
        case KeyCode.W:
          vController.move(Direction.FORWARD); 
        break;

        case KeyCode.S:
          vController.move(Direction.BACKWARD); 
        break;

        case KeyCode.A:
          vController.move(Direction.LEFT);
        break;

        case KeyCode.D:
          vController.move(Direction.RIGHT);
        break;

        case KeyCode.Q:
          vController.move(Direction.ROTATE_LEFT);
        break;

        case KeyCode.E:
          vController.move(Direction.ROTATE_RIGHT);
        break;

        case KeyCode.X:
          mouseCaptured = false;
        break;

        default:
          break;
      }
    });

    stage.setTitle("Raycaster");
    stage.setScene(scene);
    stage.show();
    Point2D center = scene.getRoot().localToScreen(scene.getWidth()/2,scene.getHeight()/2);

    // Initial clear
    gc.clearRect(0, 0, WIDTH, HEIGHT);
    Player player = vModel.getPlayer();

    new AnimationTimer(){
      @Override
      public void handle(long now){
        gc.clearRect(0,0,WIDTH,HEIGHT);
        player.positionCheck();
        for (int i = 0; i < 60; i++){
          double[] sliceData = vController.calculateColumn(i);
          if (sliceData[0] == 1){
            gc.setFill(Color.DARKSLATEGRAY);
          } else {
            gc.setFill(Color.LIGHTSLATEGREY);
          }
          gc.fillRect(sliceData[1],sliceData[2],sliceData[3],sliceData[4]);//drawing the slice
          
        }

      }
    }.start();
  }

  public static void main(String[] args) {
    launch(args);
  }
}
